import java.util.*;

class Solution {
    static void normalize(List<String> xs) {
        for (ListIterator<String> it = xs.listIterator(); it.hasNext(); ) {
            String cur = it.next();
            if (cur.isEmpty()) {
                it.set("(空)");
            } else if (cur.endsWith("!")) {
                it.add("警告");
            }
        }
    }
}

