import java.util.*;

class Solution {
    static List<Integer> topK(List<Integer> xs, int k) {
        if (k <= 0) {
            return new ArrayList<>();
        }
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        for (int x : xs) {
            heap.add(x);
            if (heap.size() > k) {
                heap.poll();
            }
        }
        List<Integer> out = new ArrayList<>(heap);
        out.sort(Comparator.reverseOrder());
        return out;
    }
}

