import java.util.*;

class Solution {
    static List<Integer> buildByPrepending(int n) {
        LinkedList<Integer> list = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            list.addFirst(i);
        }
        return list;
    }

    static long total(List<Integer> xs) {
        List<Integer> target = (xs instanceof RandomAccess) ? xs : new ArrayList<>(xs);
        long sum = 0L;
        for (int i = 0; i < target.size(); i++) {
            sum += target.get(i);
        }
        return sum;
    }
}

