class Solution {
    enum Day { MON, TUE, WED, THU, FRI, SAT, SUN }

    static Map<Day, Integer> countByDay(List<Day> days) {
        Map<Day, Integer> counts = new EnumMap<>(Day.class);
        for (Day d : days) {
            counts.merge(d, 1, Integer::sum);
        }
        return counts;
    }

    static Set<Day> weekend() {
        return EnumSet.of(Day.SAT, Day.SUN);
    }
}

