import java.util.*;

class Solution {
    static final NavigableMap<Integer, String> TABLE =
            new TreeMap<>(Map.of(0, "D", 60, "C", 70, "B", 90, "A"));

    static String gradeOf(int score) {
        Map.Entry<Integer, String> e = TABLE.floorEntry(score);
        return e == null ? null : e.getValue();
    }

    static Integer nextBoundary(int score) {
        return TABLE.higherKey(score);
    }
}

