import java.util.List;
import java.util.stream.Collectors;

class Solution {
    static List<Integer> leadingNonNegatives(List<Integer> nums) {
        return nums.stream()
                .takeWhile(n -> n >= 0)
                .collect(Collectors.toList());
    }

    static List<Integer> fromFirstNegative(List<Integer> nums) {
        return nums.stream()
                .dropWhile(n -> n >= 0)
                .collect(Collectors.toList());
    }
}

