import java.util.List;
import java.util.stream.Stream;

class Solution {
    static int buildOnlyLogSize(List<Integer> nums, List<Integer> log) {
        Stream<Integer> pipeline = nums.stream()
                .peek(log::add)
                .map(n -> n * 2);
        return log.size();
    }

    static int firstOver(List<Integer> nums, int limit, List<Integer> log) {
        return nums.stream()
                .peek(log::add)
                .filter(n -> n > limit)
                .findFirst()
                .orElse(-1);
    }
}

