interface Tally {
    int total();
}

class Solution {
    static Tally sumOf(int[] values) {
        int offset = 100;

        class Sum implements Tally {
            @Override
            public int total() {
                int sum = offset;
                for (int v : values) {
                    sum += v;
                }
                return sum;
            }
        }

        return new Sum();
    }
}

