import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.function.BiFunction;

class Solution {
    static String render(Map<String, Integer> scores) {
        StringBuilder sb = new StringBuilder();
        scores.forEach((key, value) -> sb.append(key).append('=').append(value).append(';'));
        return sb.toString();
    }

    static <K, V, R> List<R> mapEntries(Map<K, V> map, BiFunction<K, V, R> f) {
        List<R> out = new ArrayList<>();
        map.forEach((key, value) -> out.add(f.apply(key, value)));
        return out;
    }
}

