import java.util.HashMap;
import java.util.Map;

class Solution {
    static final Map<Integer, Long> CACHE = new HashMap<>();

    static long fib(int n) {
        if (n < 2) {
            return n;
        }
        Long cached = CACHE.get(n);
        if (cached != null) {
            return cached;
        }
        long value = fib(n - 1) + fib(n - 2);
        CACHE.put(n, value);
        return value;
    }
}

