class Solution {
    static String toPhone(String digits) {
        StringBuilder sb = new StringBuilder(digits);
        sb.insert(3, '-');
        sb.insert(8, '-');
        return sb.toString();
    }

    static String removeSpaces(String s) {
        StringBuilder sb = new StringBuilder(s);
        for (int i = sb.length() - 1; i >= 0; i--) {
            if (sb.charAt(i) == ' ') {
                sb.deleteCharAt(i);
            }
        }
        return sb.toString();
    }

    static String censor(String s, int start, int end) {
        StringBuilder sb = new StringBuilder(s);
        sb.replace(start, end, "*".repeat(end - start));
        return sb.toString();
    }
}

