class Solution {
    static int[] insertAt(int[] src, int index, int value) {
        int[] dst = new int[src.length + 1];
        System.arraycopy(src, 0, dst, 0, index);
        dst[index] = value;
        System.arraycopy(src, index, dst, index + 1, src.length - index);
        return dst;
    }

    static void overwrite(int[] dst, int dstPos, int[] src) {
        System.arraycopy(src, 0, dst, dstPos, src.length);
    }
}

